package io.screentrace.scanner;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.nio.charset.Charset;import static org.junit.jupiter.api.Assertions.*;
class DeclaredSourceEncodingTest {
 @TempDir Path root;
 @Test void sourceDeclarationDecodesWithoutChangingBytes()throws Exception{var p=root.resolve("legacy.jsp");var original="<%@ page pageEncoding=\"GB18030\"%><title>物料</title>".getBytes(Charset.forName("GB18030"));Files.write(p,original);assertTrue(SafeProjectFiles.readUtf8Limited(root,p,1024).contains("物料"));assertArrayEquals(original,Files.readAllBytes(p));}
 @Test void unknownDeclarationIsReportedAndReadAsUtf8()throws Exception{var p=root.resolve("bad.jsp");Files.writeString(p,"<%@ page pageEncoding=\"made-up\"%><form action=\"/save.do\">");assertTrue(SafeProjectFiles.readUtf8Limited(root,p,1024).contains("/save.do"));assertNotNull(SafeProjectFiles.decodingProblem(p,Files.readAllBytes(p)));}
 @Test void big5DeclarationIsDecoded()throws Exception{var p=root.resolve("tw.jsp");var original="<%@ page pageEncoding=\"Big5\"%><title>訂單查詢</title>".getBytes(Charset.forName("Big5"));Files.write(p,original);assertTrue(SafeProjectFiles.readUtf8Limited(root,p,1024).contains("訂單查詢"));assertNull(SafeProjectFiles.decodingProblem(p,original));}
 @Test void shiftJisAndMs950DeclarationsAreSupported()throws Exception{for(var e:java.util.Map.of("jp.jsp","Shift_JIS","ms.jsp","MS950").entrySet()){var p=root.resolve(e.getKey());Files.write(p,("<%@ page pageEncoding=\""+e.getValue()+"\"%><p>表示</p>").getBytes(Charset.forName(e.getValue())));assertTrue(SafeProjectFiles.readUtf8Limited(root,p,1024).contains("表示"),e.getValue());}}
 @Test void malformedBytesKeepTheFileReadable()throws Exception{var p=root.resolve("broken.jsp");var bytes=new java.io.ByteArrayOutputStream();bytes.write("<%@ page pageEncoding=\"GBK\"%><a href=\"/next.do\">".getBytes(Charset.forName("GBK")));bytes.write(new byte[]{(byte)0x81,(byte)0x20});Files.write(p,bytes.toByteArray());assertTrue(SafeProjectFiles.readUtf8Limited(root,p,1024).contains("/next.do"));assertNotNull(SafeProjectFiles.decodingProblem(p,bytes.toByteArray()));}
}
